import json, pathlib, shutil, socket, subprocess, time, urllib.request
from datetime import datetime, timezone

def run(args, timeout=5):
    try:
        p=subprocess.run(args,capture_output=True,text=True,timeout=timeout)
        return p.returncode,(p.stdout or '').strip(),(p.stderr or '').strip()
    except Exception as e:
        return 999,'',type(e).__name__

def unit(name, user=True):
    base=['systemctl']+(['--user'] if user else [])
    _,active,_=run(base+['is-active',name],3)
    _,enabled,_=run(base+['is-enabled',name],3)
    _,show,_=run(base+['show',name,'-p','Result','-p','ExecMainStatus','-p','StateChangeTimestamp','--no-pager'],3)
    d={'active':active or 'unknown','enabled':enabled or 'unknown'}
    for line in show.splitlines():
        if '=' in line:
            k,v=line.split('=',1); d[k]=v
    return d

def http_json(url):
    try:
        with urllib.request.urlopen(url,timeout=4) as r:
            b=r.read(65536)
